/* Influencer Dashboard — renderers.
 *
 * Renderers ONLY: this file consumes window.DATA (the single source of truth
 * generated by scripts/generate-data.py) and renders it into index.html.
 * It performs NO derived-rollup computation — all rollups come precomputed
 * from data.js > derived.
 *
 * Every component is one render function (resources/design-spec.md §6), and
 * every class string comes from the spec's tokens (§3) and type scale (§4).
 */
(function () {
  "use strict";

  var DATA = window.DATA;

  if (!DATA || !DATA.derived) {
    console.error("Influencer Dashboard: window.DATA not found. Did data.js load before app.js?");
    return;
  }

  var derived = DATA.derived;

  /* ---------- tokens (design-spec §3, §4) ---------- */

  var T = {
    card: "bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-xl shadow-sm p-4 lg:p-6 min-w-0",
    label: "text-xs font-semibold uppercase tracking-wide text-gray-500 dark:text-slate-400",
    kpiValue: "text-3xl lg:text-4xl font-bold tracking-tight tabular-nums",
    heading: "text-gray-900 dark:text-slate-100",
    body: "text-gray-600 dark:text-slate-300",
    muted: "text-gray-500 dark:text-slate-400",
    badge: "inline-flex items-center gap-0.5 whitespace-nowrap rounded-full px-2 py-0.5 text-xs font-medium",
    up: "bg-green-100 text-green-800 dark:bg-green-500/15 dark:text-green-300",
    down: "bg-red-100 text-red-800 dark:bg-red-500/15 dark:text-red-300",
    activeNav: ["text-sky-700", "dark:text-sky-400"]
  };

  var ACCENT = {
    revenue: { chip: "bg-emerald-100 dark:bg-emerald-500/20", color: "#10b981" },
    volume: { chip: "bg-sky-100 dark:bg-sky-500/20", color: "#0ea5e9" },
    engagement: { chip: "bg-violet-100 dark:bg-violet-500/20", color: "#8b5cf6" },
    performance: { chip: "bg-indigo-100 dark:bg-indigo-500/20", color: "#6366f1" }
  };

  /* ---------- tiny DOM helpers (textContent only — no HTML injection) ---------- */

  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined && text !== null) node.textContent = text;
    return node;
  }

  /* ---------- number formatting (design-spec §4) ---------- */

  function usd(value) {
    return "$" + Number(value).toLocaleString("en-US", { maximumFractionDigits: 0 });
  }

  function pct(value) {
    return Number(value).toFixed(1) + "%";
  }

  function count(value) {
    return Number(value).toLocaleString("en-US");
  }

  function compact(value) {
    return Number(value).toLocaleString("en-US", { notation: "compact", maximumFractionDigits: 1 });
  }

  var platformName = {};
  DATA.platforms.forEach(function (p) { platformName[p.id] = p.name; });

  /* ---------- components (design-spec §6) ---------- */

  function card(title) {
    var node = el("article", T.card);
    node.appendChild(el("h3", T.label + " mb-4", title));
    return node;
  }

  // unit: "%" for relative change, "pt" for percentage-point change.
  function trendBadge(value, unit) {
    var positive = Number(value) >= 0;
    var magnitude = Math.abs(Number(value)).toFixed(1) + unit;
    var badge = el("span", T.badge + " " + (positive ? T.up : T.down),
      (positive ? "▲ " : "▼ ") + magnitude);
    badge.setAttribute("aria-label", (positive ? "up " : "down ") + magnitude + " vs last month");
    return badge;
  }

  function kpiCard(opts) {
    var node = el("article", T.card);

    var head = el("div", "flex items-start justify-between gap-3 mb-3");
    head.appendChild(el("h3", T.label + " pt-1", opts.label));
    var chip = el("span", "flex shrink-0 items-center justify-center w-10 h-10 rounded-lg text-lg " + opts.accent.chip, opts.icon);
    chip.setAttribute("aria-hidden", "true");
    head.appendChild(chip);
    node.appendChild(head);

    node.appendChild(el("p", T.kpiValue, opts.value));

    var foot = el("p", "mt-2 flex flex-wrap items-center gap-x-2 gap-y-1 text-sm");
    if (opts.delta) foot.appendChild(opts.delta);
    if (opts.sub) foot.appendChild(el("span", T.muted, opts.sub));
    node.appendChild(foot);
    return node;
  }

  // rows: [{ label, value, display }]. Bars are scaled to the largest value × 0.75
  // so the outside label of the longest bar still fits (design-spec §7).
  function barChart(opts) {
    var node = card(opts.title);
    var max = 0;
    opts.rows.forEach(function (r) { if (r.value > max) max = r.value; });

    var table = el("table", "charts-css bar show-labels data-outside data-spacing-10");
    table.style.setProperty("--labels-size", "6.5rem");
    table.appendChild(el("caption", "sr-only", opts.caption));

    var tbody = el("tbody");
    opts.rows.forEach(function (r) {
      var row = el("tr");
      var th = el("th", "text-sm font-medium " + T.body, r.label);
      th.setAttribute("scope", "row");
      row.appendChild(th);

      var td = el("td");
      td.style.setProperty("--size", String(max > 0 ? (r.value / max) * 0.75 : 0));
      td.style.setProperty("--color", opts.color);
      td.appendChild(el("span", "data whitespace-nowrap text-sm tabular-nums ps-2 " + T.heading, r.display));
      row.appendChild(td);
      tbody.appendChild(row);
    });
    table.appendChild(tbody);
    node.appendChild(table);
    return node;
  }

  // columns: [{ title, numeric }]; rows: arrays of cell strings, or { text, className } objects.
  function dataTable(opts) {
    var node = card(opts.title);
    node.className += " lg:col-span-2";

    var wrap = el("div", "overflow-x-auto");
    var table = el("table", "w-full text-sm");

    var thead = el("thead");
    var headRow = el("tr", "bg-gray-50 dark:bg-slate-700/50 " + T.label);
    opts.columns.forEach(function (c) {
      var th = el("th", "px-3 py-3 whitespace-nowrap " + (c.numeric ? "text-right" : "text-left"), c.title);
      th.setAttribute("scope", "col");
      headRow.appendChild(th);
    });
    thead.appendChild(headRow);
    table.appendChild(thead);

    var tbody = el("tbody", "divide-y divide-gray-200 dark:divide-slate-700");
    opts.rows.forEach(function (cells) {
      var tr = el("tr", "hover:bg-gray-50 dark:hover:bg-slate-700/40 transition-colors duration-150 motion-reduce:transition-none");
      cells.forEach(function (cell, i) {
        var numeric = opts.columns[i].numeric;
        var text = typeof cell === "object" ? cell.text : cell;
        var extra = typeof cell === "object" ? cell.className : T.body;
        tr.appendChild(el("td", "px-3 py-3 whitespace-nowrap " + (numeric ? "text-right tabular-nums " : "") + extra, text));
      });
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);

    wrap.appendChild(table);
    node.appendChild(wrap);
    return node;
  }

  /* ---------- 1. KPI cards (design-spec §8: Revenue, Volume, Engagement, Performance) ---------- */

  var kpiGrid = document.getElementById("kpi-grid");
  if (kpiGrid) {
    [
      kpiCard({
        label: "Total Commissions",
        value: usd(derived.totalCommission),
        delta: trendBadge(derived.totalCommissionDeltaPct, "%"),
        sub: "Top: " + (platformName[derived.topPlatform] || derived.topPlatform),
        accent: ACCENT.revenue,
        icon: "💰"
      }),
      kpiCard({
        label: "Units Sold",
        value: count(derived.unitsSold),
        delta: trendBadge(derived.unitsSoldDeltaPct, "%"),
        sub: compact(derived.totalImpressions) + " impressions",
        accent: ACCENT.volume,
        icon: "📦"
      }),
      kpiCard({
        label: "Engagement Rate",
        value: pct(derived.avgEngagementRate),
        delta: trendBadge(derived.avgEngagementDeltaPct, "pt"),
        sub: "all platforms",
        accent: ACCENT.engagement,
        icon: "❤️"
      }),
      kpiCard({
        label: "Conversion Rate",
        value: pct(derived.overallConversionRate),
        delta: null,
        sub: pct(derived.overallCtr) + " click-through",
        accent: ACCENT.performance,
        icon: "🎯"
      })
    ].forEach(function (c) { kpiGrid.appendChild(c); });
  }

  /* ---------- 2. Drivers ---------- */

  var driverGrid = document.getElementById("driver-grid");
  if (driverGrid) {
    driverGrid.appendChild(barChart({
      title: "Commission Share by Platform",
      caption: "Share of total commission earned on each platform, in percent",
      color: ACCENT.revenue.color,
      rows: DATA.platforms.map(function (p) {
        var share = derived.platformRevenueShare[p.id] || 0;
        return { label: p.name, value: share, display: pct(share) };
      })
    }));
  }

  /* ---------- 3. Operational details ---------- */

  var detailGrid = document.getElementById("detail-grid");
  if (detailGrid) {
    detailGrid.appendChild(dataTable({
      title: "Products",
      columns: [
        { title: "Product" },
        { title: "Price", numeric: true },
        { title: "Units Sold", numeric: true },
        { title: "Revenue", numeric: true },
        { title: "Commission", numeric: true },
        { title: "Conv. Rate", numeric: true },
        { title: "Top Channel" }
      ],
      rows: DATA.products.map(function (prod) {
        var topChannelId = null;
        var topChannelVal = -1;
        Object.keys(prod.platformShare || {}).forEach(function (plId) {
          if (prod.platformShare[plId] > topChannelVal) {
            topChannelVal = prod.platformShare[plId];
            topChannelId = plId;
          }
        });
        return [
          { text: prod.name, className: "font-medium " + T.heading },
          usd(prod.price),
          count(prod.unitsSold),
          { text: usd(prod.revenue), className: "font-medium " + T.heading },
          { text: usd(prod.commission), className: "font-medium " + T.heading },
          pct(prod.conversionRate),
          platformName[topChannelId] || topChannelId
        ];
      })
    }));
  }

  /* ---------- 4. Footer meta ---------- */

  var footerPeriod = document.getElementById("footer-period");
  if (footerPeriod && DATA.meta && DATA.meta.period) {
    footerPeriod.textContent = DATA.meta.period.start + " – " + DATA.meta.period.end;
  }

  /* ---------- 5. Theme toggle (design-spec §9) ---------- */

  var toggle = document.getElementById("theme-toggle");
  if (toggle) {
    var root = document.documentElement;
    var icon = toggle.querySelector("[aria-hidden]");
    var syncToggle = function () {
      var dark = root.classList.contains("dark");
      toggle.setAttribute("aria-pressed", dark ? "true" : "false");
      if (icon) icon.textContent = dark ? "\uD83C\uDF19" : "\u2600\uFE0F";
    };
    syncToggle();
    toggle.addEventListener("click", function () {
      var dark = root.classList.toggle("dark");
      try { localStorage.setItem("theme", dark ? "dark" : "light"); } catch (e) {}
      syncToggle();
    });
  }

  /* ---------- 6. Scroll-spy for nav (aria-current on active section link) ---------- */

  var navLinks = Array.prototype.slice.call(document.querySelectorAll("nav .nav-link"));
  var sections = ["kpis", "drivers", "details"]
    .map(function (id) { return document.getElementById(id); })
    .filter(Boolean);

  function setActive(id) {
    navLinks.forEach(function (link) {
      var isActive = link.getAttribute("href") === "#" + id;
      if (isActive) {
        link.setAttribute("aria-current", "true");
        link.classList.add.apply(link.classList, T.activeNav);
      } else {
        link.removeAttribute("aria-current");
        link.classList.remove.apply(link.classList, T.activeNav);
      }
    });
  }

  if ("IntersectionObserver" in window && navLinks.length && sections.length) {
    var observer = new IntersectionObserver(function (entries) {
      // Near the top of the page the first block is always the active one.
      if (window.scrollY < 80) return setActive(sections[0].id);
      entries.forEach(function (entry) {
        if (entry.isIntersecting) setActive(entry.target.id);
      });
    }, { rootMargin: "-40% 0px -55% 0px", threshold: 0 });
    sections.forEach(function (s) { observer.observe(s); });
    window.addEventListener("scroll", function () {
      if (window.scrollY < 80) setActive(sections[0].id);
    }, { passive: true });
    setActive(sections[0].id);
  }
})();
